import { createHmac } from "node:crypto";
import { Buffer } from "node:buffer";
export default function f({ body, secret }) {
  const { payload, signature } = body ?? {};
  if (!payload || !signature || !secret) throw Error("Missing signed relay event");
  const expected = createHmac("sha256", secret).update(payload, "utf8").digest(),
    actual = Buffer.from(signature, "base64");
  let diff = actual.length ^ expected.length;
  for (let i = 0; i < expected.length; i++) diff |= expected[i] ^ (actual[i] ?? 0);
  if (diff !== 0) throw Error("Invalid relay signature");
  const e = JSON.parse(Buffer.from(payload, "base64").toString("utf8"));
  if (
    e.type !== "message" ||
    !e.webhookEventId ||
    !e.message?.id ||
    !["image", "video", "audio", "file"].includes(e.message.type)
  )
    throw Error("Unsupported LINE event");
  return {
    event: e,
    id: e.webhookEventId,
    messageId: e.message.id,
    type: e.message.type,
    replyToken: e.replyToken ?? "",
    timestamp: e.timestamp,
  };
}

