export default async function f({ id, ack, resolution }, ctx) {
  const key = "line-file:" + id,
    s = await ctx.state.get(key);
  if (s?.phase === "done") return { key, skip: true };
  if (s) {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect previous LINE event " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { ...s, phase: "done" });
      return { key, skip: true };
    }
    await ctx.state.set(key, null);
  }
  await ctx.state.set(key, { phase: "pending", eventId: id });
  return { key, skip: false };
}

