export default function f({ rows, event }) {
  if (!Array.isArray(rows) || rows.length < 2) throw Error("Missing config");
  const c = Object.fromEntries(rows[0].map((k, i) => [k, rows[1][i]])),
    yes = (x) => x === true || String(x).toLowerCase() === "true";
  if (!c["Parent Folder ID"]) throw Error("Missing parent folder");
  const allowed = String(c["Allow File Types"] ?? "")
    .toLowerCase()
    .split("|")
    .map((x) => x.trim());
  return {
    parent: String(c["Parent Folder ID"]),
    byDate: yes(c["Store by Date"]),
    byType: yes(c["Store by File Type"]),
    reply: yes(c["Reply Enabled"]),
    allowed: allowed.includes(event.message.type),
    date: String(
      c.CurrentDate || new Date(event.timestamp).toISOString().slice(0, 10).replaceAll("-", ""),
    ),
  };
}

