export default async function f({ key, parent, date, type, byDate, byType }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== "pending") throw Error("Missing event checkpoint");
  if (!s.folder)
    s.folder = { parent, index: 0, names: [...(byDate ? [date] : []), ...(byType ? [type] : [])] };
  const f = s.folder,
    name = f.names[f.index];
  await ctx.state.set(key, s);
  if (!name) return { done: true, parent: f.parent, name: "-", query: "-", parents: [f.parent] };
  if (!/^[\w-]+$/.test(f.parent) || /[\\/\x00-\x1f]/.test(name)) throw Error("Invalid folder");
  return {
    done: false,
    parent: f.parent,
    name,
    query:
      "'" +
      f.parent +
      "' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false and name = '" +
      name.replaceAll("'", "\\'") +
      "'",
    parents: [f.parent],
  };
}

