export default async function f({ key, id }, ctx) {
  if (!id || id === "-") throw Error("Missing folder ID");
  const s = await ctx.state.get(key);
  if (s?.phase !== "pending" || !s.folder) throw Error("Missing folder checkpoint");
  s.folder.parent = id;
  s.folder.index++;
  await ctx.state.set(key, s);
  return { ok: true };
}

