export default function f({ body, status, id, previous }) {
  let s = previous ?? { count: 0 };
  if (++s.count > 120) throw Error("Inspect media upload");
  if (status !== 200 || body?.requestId !== id) throw Error("Invalid upload status");
  if (body.status === "done" && body.fileId)
    return {
      state: s,
      done: true,
      fileId: body.fileId,
      name: body.name ?? "",
      url: body.url ?? "",
      created: body.created ?? "",
      extension: body.extension ?? "",
    };
  if (body.status !== "pending") throw Error("Inspect media upload");
  return { state: s, done: false, fileId: "-", name: "", url: "", created: "", extension: "" };
}

