export default async function f({ count, key, url }, ctx) {
  if (count !== 1) throw Error("Inspect Sheets append");
  const s = await ctx.state.get(key);
  if (s?.phase !== "pending") throw Error("Missing event checkpoint");
  await ctx.state.set(key, { ...s, url });
  return { ok: true };
}

