export default async function f({ allowed, key, replyToken }, ctx) {
  const url = (await ctx.state.get(key))?.url;
  if (!replyToken) throw Error("Missing reply token");
  if (allowed && !url) throw Error("Missing Drive URL");
  return {
    body: {
      replyToken,
      messages: [{ type: "text", text: allowed ? url : "This file type is not allowed." }],
    },
  };
}

